import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Protocol and idempotency","description":"","frontmatter":{"pageId":"developers/protocol","contentRevision":2},"headers":[],"relativePath":"en/developers/protocol.md","filePath":"en/developers/protocol.md"}'),i={name:"en/developers/protocol.md"};function n(s,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="protocol-and-idempotency" tabindex="-1">Protocol and idempotency <a class="header-anchor" href="#protocol-and-idempotency" aria-label="Permalink to &quot;Protocol and idempotency&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>The protocol only grows: add fields with new numbers, messages, proto files, ErrorCodes and ServerEvent bodies. Never reuse numbers. events.proto imports feature protos; features must not import events.proto and create a cycle.</p><p>Mutations use client_request_id. Unknown outcomes after disconnect are retried through the outbox with the same ID and original intent; a new ID means a new operation. Validate names, sizes, paths, limits and legal state at the boundary. Rate/size refusals return typed ErrorCodes rather than escaping crashes.</p><p>ProtocolVersion.Current is 1 and changes for incompatible contracts, not every release. Additive wire compatibility does not mean an old client displays a new feature.</p><h2 id="mutation-contract" tabindex="-1">A mutation contract is more than a protobuf field <a class="header-anchor" href="#mutation-contract" aria-label="Permalink to &quot;A mutation contract is more than a protobuf field {#mutation-contract}&quot;">​</a></h2><p>Specify input, authority, state predicate, atomic result and retry behavior for a mutation. Persist client_request_id with original data until a definite outcome. Timeout is not proof of server rollback. Reusing the ID must retain result semantics; changing its payload must not create a new operation.</p><p>Test size/name/permission refusal before effects, concurrent requests and replay after commit before response. Live rows must be read inside LiveStateLock; checking outside races.</p><p>Wire compatibility, UI version and collection hash are separate. A new message does not authorize unsupported old-client UX without defined behavior.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>A schema does not establish authorization: enforce permissions on the server. Influence expected version/context and requestId protect against delayed operations. Do not log secret-bearing payloads for debugging.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./storage">Storage and escrow</a></li><li><a href="./client">Client, mod and live</a></li><li><a href="./../admins/api">REST API reference</a></li></ul>',14)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
